('Invasion mongole de Bagdad', 'invasion-mongole-bagdad-irak-IQ', '1258-01-01', '1258-01-01', 'Les Mongols dirigés par Hulagu Khan prennent Bagdad et mettent fin au califat abbasside de Bagdad.', NULL, 13),
('Prise de Bagdad par les Ilkhanides', 'prise-bagdad-ilkhanides-irak-IQ', '1258-01-01', '1258-01-01', 'Bagdad passe sous domination mongole et devient intégrée à l Ilkhanat.', NULL, 12),
('Conquête ottomane de Bagdad', 'conquete-ottomane-bagdad-irak-IQ', '1534-12-01', '1534-12-01', 'Les Ottomans prennent Bagdad au cours de leur conflit avec les Safavides.', NULL, 12),
('Prise de Bagdad par les Safavides', 'prise-bagdad-safavides-irak-IQ', '1623-01-01', '1623-01-01', 'Les forces safavides reprennent Bagdad aux Ottomans.', NULL, 12),
('Reprise ottomane de Bagdad', 'reprise-ottomane-bagdad-irak-IQ', '1638-12-01', '1638-12-01', 'Les Ottomans reprennent Bagdad aux Safavides et rétablissent leur domination sur la ville.', NULL, 12),
('Révolte irakienne de 1920', 'revolte-irakienne-1920-IQ', '1920-06-01', '1920-10-01', 'Une vaste révolte éclate contre le mandat britannique en Irak.', NULL, 9),
('Indépendance de l Irak', 'independance-irak-IQ', '1932-10-03', '1932-10-03', 'L Irak devient officiellement indépendant et rejoint la Société des Nations.', NULL, 11),
('Coup d État du 14 juillet en Irak', 'coup-etat-14-juillet-irak-IQ', '1958-07-14', '1958-07-14', 'Un coup d État renverse la monarchie irakienne et proclame la république.', NULL, 10);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Règne des rois parthes', 'regne-rois-parthes-iran-IR', '0001-01-01', '0224-01-01', 'L Empire parthe domine une grande partie du plateau iranien et contrôle d importants axes commerciaux entre l Asie et le Proche-Orient.', NULL, 5),
('Développement du zoroastrisme sous les Sassanides', 'developpement-zoroastrisme-sassanides-iran-IR', '0224-01-01', '0651-01-01', 'Le zoroastrisme occupe une place centrale dans l organisation religieuse et politique de l Empire sassanide.', NULL, 23),
('Fondation de l Empire sassanide', 'fondation-empire-sassanide-iran-IR', '0224-01-01', '0224-01-01', 'Ardashir Ier renverse les Arsacides et fonde l Empire sassanide en Iran.', NULL, 16),
('Règne de Shapur Ier', 'regne-shapur-ier-iran-IR', '0240-01-01', '0270-01-01', 'Shapur Ier renforce l Empire sassanide et étend son influence en Mésopotamie et en Asie occidentale.', NULL, 5),
('Développement de l art sassanide', 'developpement-art-sassanide-iran-IR', '0300-01-01', '0650-01-01', 'L art sassanide se développe dans l architecture, la sculpture, l orfèvrerie et les textiles.', NULL, 24),
('Conquête musulmane de la Perse', 'conquete-musulmane-perse-iran-IR', '0633-01-01', '0651-01-01', 'Les armées du califat conquièrent progressivement l Empire sassanide et mettent fin à son indépendance politique.', NULL, 12),
('Bataille de Nahavand', 'bataille-nahavand-iran-IR', '0642-01-01', '0642-01-01', 'La défaite sassanide à Nahavand accélère la conquête arabe de la Perse.', NULL, 7),
('Fondation de la dynastie samanide en Perse orientale', 'fondation-dynastie-samanide-perse-orientale-iran-IR', '0819-01-01', '0819-01-01', 'Les Samanides établissent leur pouvoir en Iran oriental et en Transoxiane.', NULL, 16),
('Fondation de la dynastie seldjoukide', 'fondation-dynastie-seldjoukide-iran-IR', '1037-01-01', '1037-01-01', 'Les Seldjoukides établissent un puissant empire couvrant une grande partie de l Iran.', NULL, 16),
('Règne de Malik Shah Ier', 'regne-malik-shah-ier-iran-IR', '1072-01-01', '1092-01-01', 'Malik Shah Ier dirige l Empire seldjoukide à son apogée et favorise les sciences et l administration.', NULL, 5),
('Fondation de l observatoire de Maragha', 'fondation-observatoire-maragha-iran-IR', '1259-01-01', '1259-01-01', 'Nasir al-Din al-Tusi fonde l observatoire de Maragha sous les Ilkhanides.', NULL, 18),
('Fondation de la dynastie safavide', 'fondation-dynastie-safavide-iran-IR', '1501-01-01', '1501-01-01', 'Ismail Ier fonde la dynastie safavide et établit un État iranien durable.', NULL, 16),
('Adoption du chiisme duodécimain comme religion d État', 'adoption-chiisme-religion-etat-iran-IR', '1501-01-01', '1501-01-01', 'Ismail Ier fait du chiisme duodécimain la religion officielle de l État safavide.', NULL, 23),
('Règne de Shah Abbas Ier', 'regne-shah-abbas-ier-iran-IR', '1588-01-01', '1629-01-01', 'Shah Abbas Ier renforce l État safavide et développe Ispahan comme centre politique et culturel.', NULL, 5),
('Construction de la place Naqsh-e Jahan', 'construction-place-naqsh-e-jahan-iran-IR', '1598-01-01', '1629-01-01', 'La place Naqsh-e Jahan et ses monuments sont développés à Ispahan sous Shah Abbas Ier.', NULL, 17),
('Chute de la dynastie safavide', 'chute-dynastie-safavide-iran-IR', '1722-01-01', '1722-01-01', 'Les forces afghanes de Mahmoud Hotaki prennent Ispahan et provoquent la chute du pouvoir safavide.', NULL, 12),
('Fondation de la dynastie qadjare', 'fondation-dynastie-qadjare-iran-IR', '1789-01-01', '1789-01-01', 'Agha Mohammad Khan établit la dynastie qadjare et réunifie progressivement l Iran.', NULL, 16),
('Révolution constitutionnelle perse', 'revolution-constitutionnelle-perse-iran-IR', '1905-12-01', '1911-01-01', 'La Révolution constitutionnelle impose progressivement une monarchie constitutionnelle et la création d un parlement.', NULL, 8),
('Coup d État de 1953 en Iran', 'coup-etat-1953-iran-IR', '1953-08-19', '1953-08-19', 'Un coup d État renverse le gouvernement de Mohammad Mossadegh et renforce le pouvoir du Shah.', NULL, 10),
('Révolution iranienne', 'revolution-iranienne-iran-IR', '1978-01-01', '1979-02-11', 'Une mobilisation politique et sociale renverse la monarchie et conduit à la création de la République islamique.', NULL, 8);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement de la présence romaine en Judée', 'developpement-presence-romaine-judee-israel-IL', '0006-01-01', '0066-01-01', 'La Judée passe progressivement sous domination romaine après son intégration dans le système provincial romain.', NULL, 12),
('Grande révolte juive contre Rome', 'grande-revolte-juive-rome-israel-IL', '0066-01-01', '0073-01-01', 'Une grande révolte éclate en Judée contre l Empire romain et se termine après la chute de plusieurs places fortes.', NULL, 9),
('Destruction du Second Temple', 'destruction-second-temple-israel-IL', '0070-08-04', '0070-08-04', 'Les forces romaines détruisent le Second Temple de Jérusalem pendant la Grande révolte juive.', NULL, 20),
('Révolte de Bar Kokhba', 'revolte-bar-kokhba-israel-IL', '0132-01-01', '0135-01-01', 'La révolte menée par Simon Bar Kokhba contre Rome éclate en Judée et est finalement écrasée par les forces romaines.', NULL, 9),
('Conquête arabe de la Palestine', 'conquete-arabe-palestine-israel-IL', '0634-01-01', '0638-01-01', 'Les armées du califat conquièrent progressivement la Palestine et Jérusalem passe sous domination musulmane.', NULL, 12),
('Conquête croisée de Jérusalem', 'conquete-croisee-jerusalem-israel-IL', '1099-07-15', '1099-07-15', 'Les croisés prennent Jérusalem lors de la Première croisade et établissent le royaume de Jérusalem.', NULL, 12),
('Reprise de Jérusalem par Saladin', 'reprise-jerusalem-saladin-israel-IL', '1187-10-02', '1187-10-02', 'Les forces de Saladin reprennent Jérusalem après la bataille de Hattin.', NULL, 12),
('Conquête ottomane de Jérusalem', 'conquete-ottomane-jerusalem-israel-IL', '1517-01-01', '1517-01-01', 'Les Ottomans prennent le contrôle de Jérusalem et de la Palestine au détriment des Mamelouks.', NULL, 12),
('Déclaration Balfour', 'declaration-balfour-israel-IL', '1917-11-02', '1917-11-02', 'Le gouvernement britannique publie la Déclaration Balfour concernant l établissement d un foyer national juif en Palestine.', NULL, 22),
('Début du mandat britannique sur la Palestine', 'debut-mandat-britannique-palestine-israel-IL', '1920-04-25', '1920-04-25', 'La Société des Nations approuve le mandat britannique sur la Palestine.', NULL, 22),
('Création de l Agence juive', 'creation-agence-juive-israel-IL', '1929-08-11', '1929-08-11', 'L Agence juive pour la Palestine est constituée comme institution représentative du mouvement sioniste.', NULL, 17),
('Plan de partage de la Palestine', 'plan-partage-palestine-israel-IL', '1947-11-29', '1947-11-29', 'L Assemblée générale des Nations unies adopte la résolution 181 proposant la création d un État juif et d un État arabe en Palestine.', NULL, 22),
('Proclamation de l État d Israël', 'proclamation-etat-israel-israel-IL', '1948-05-14', '1948-05-14', 'David Ben-Gourion proclame la création de l État d Israël à la fin du mandat britannique.', NULL, 11),
('Guerre israélo-arabe de 1948', 'guerre-israelo-arabe-1948-israel-IL', '1948-05-15', '1949-07-20', 'Une guerre oppose Israël à plusieurs États arabes voisins après la proclamation de l indépendance israélienne.', NULL, 6),
('Admission d Israël à l ONU', 'admission-israel-onu-israel-IL', '1949-05-11', '1949-05-11', 'Israël devient membre de l Organisation des Nations unies.', NULL, 22),
('Crise de Suez', 'crise-suez-israel-IL', '1956-10-29', '1956-11-07', 'Israël participe à la campagne militaire menée avec la France et le Royaume-Uni contre l Égypte lors de la crise de Suez.', NULL, 6),
('Guerre des Six Jours', 'guerre-six-jours-israel-IL', '1967-06-05', '1967-06-10', 'Israël affronte l Égypte, la Jordanie et la Syrie pendant la guerre de juin 1967.', NULL, 6),
('Guerre du Kippour', 'guerre-kippour-israel-IL', '1973-10-06', '1973-10-25', 'L Égypte et la Syrie attaquent les forces israéliennes dans le Sinaï et sur le plateau du Golan.', NULL, 6),
('Traité de paix israélo-égyptien', 'traite-paix-israelo-egyptien-israel-IL', '1979-03-26', '1979-03-26', 'Israël et l Égypte signent un traité de paix après les négociations issues des accords de Camp David.', NULL, 14),
('Accords d Oslo', 'accords-oslo-israel-IL', '1993-09-13', '1993-09-13', 'Israël et l Organisation de libération de la Palestine signent une déclaration de principes établissant un cadre pour une autonomie palestinienne intérimaire.', NULL, 14);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
