('Introduction du bouddhisme au Japon', 'introduction-bouddhisme-japon-JP', '0538-01-01', '0538-01-01', 'Le bouddhisme est introduit au Japon depuis la péninsule coréenne et commence à se diffuser dans l archipel.', NULL, 23),
('Réformes de Taika', 'reformes-taika-japon-JP', '0645-01-01', '0646-01-01', 'Les réformes de Taika renforcent l autorité impériale et réorganisent l administration de l État japonais.', NULL, 22),
('Fondation de Nara comme capitale', 'fondation-nara-capitale-japon-JP', '0710-01-01', '0710-01-01', 'Nara devient la capitale permanente du Japon et un important centre politique et religieux.', NULL, 16),
('Construction du Tōdai-ji', 'construction-todai-ji-japon-JP', '0743-01-01', '0752-01-01', 'Le grand temple bouddhique Tōdai-ji est construit à Nara et abrite le Grand Bouddha.', NULL, 17),
('Fondation de Heian-kyō', 'fondation-heian-kyo-japon-JP', '0794-01-01', '0794-01-01', 'L empereur Kanmu transfère la capitale à Heian-kyō, l actuelle Kyoto.', NULL, 16),
('Développement de la période Heian', 'developpement-periode-heian-japon-JP', '0794-01-01', '1185-01-01', 'La cour impériale de Kyoto connaît un important développement culturel, littéraire et artistique.', NULL, 24),
