('Développement de l influence khmère', 'developpement-influence-khmere-laos-LA', '0900-01-01', '1200-01-01', 'L influence politique et culturelle de l Empire khmer s étend à certaines régions du Laos actuel.', NULL, 5),
('Développement des principautés Tai', 'developpement-principautes-tai-laos-LA', '1100-01-01', '1300-01-01', 'Des principautés tai s établissent progressivement dans les vallées du nord et du centre du Laos.', NULL, 5),
('Fondation de Muang Sua', 'fondation-muang-sua-laos-LA', '1200-01-01', '1200-01-01', 'Muang Sua, future Luang Prabang, devient un important centre politique de la région du Haut-Mékong.', NULL, 16),
('Fondation du royaume de Lan Xang', 'fondation-royaume-lan-xang-laos-LA', '1353-01-01', '1353-01-01', 'Fa Ngum fonde le royaume de Lan Xang, qui devient le principal État lao médiéval.', NULL, 16),
('Diffusion du bouddhisme theravada à Lan Xang', 'diffusion-bouddhisme-theravada-lan-xang-laos-LA', '1353-01-01', '1371-01-01', 'Le bouddhisme theravada devient progressivement la principale tradition religieuse du royaume de Lan Xang.', NULL, 23),
('Règne de Setthathirath', 'regne-setthathirath-laos-LA', '1534-01-01', '1572-01-01', 'Le règne de Setthathirath correspond à une période importante de consolidation politique et religieuse de Lan Xang.', NULL, 5),
('Construction du That Luang', 'construction-that-luang-laos-LA', '1566-01-01', '1566-01-01', 'Le That Luang de Vientiane est construit sous le règne de Setthathirath et devient un symbole majeur du Laos.', NULL, 17),
('Transfert de la capitale à Vientiane', 'transfert-capitale-vientiane-laos-LA', '1560-01-01', '1560-01-01', 'Setthathirath transfère la capitale de Lan Xang à Vientiane.', NULL, 22),
('Invasion birmane de Lan Xang', 'invasion-birmane-lan-xang-laos-LA', '1574-01-01', '1574-01-01', 'Les forces birmanes envahissent Lan Xang et prennent temporairement le contrôle de Vientiane.', NULL, 13),
('Division de Lan Xang', 'division-lan-xang-laos-LA', '1707-01-01', '1713-01-01', 'La disparition de l unité politique de Lan Xang entraîne la formation de plusieurs royaumes lao.', NULL, 22),
('Fondation du royaume de Vientiane', 'fondation-royaume-vientiane-laos-LA', '1707-01-01', '1707-01-01', 'Le royaume de Vientiane devient l un des principaux États issus de la fragmentation de Lan Xang.', NULL, 16),
('Conquête siamoise de Vientiane', 'conquete-siamoise-vientiane-laos-LA', '1827-01-01', '1828-01-01', 'Les forces siamoises détruisent Vientiane et mettent fin à l indépendance du royaume.', NULL, 12),
('Établissement du protectorat français', 'protectorat-francais-laos-LA', '1893-10-03', '1893-10-03', 'Le Siam reconnaît la présence française à l est du Mékong et le Laos entre dans la sphère coloniale française.', NULL, 14),
('Royaume du Laos', 'fondation-royaume-du-laos-LA', '1949-07-19', '1949-07-19', 'Le Laos obtient une autonomie accrue au sein de l Union française et devient un État associé.', NULL, 16),
('Indépendance du Laos', 'independance-laos-LA', '1953-10-22', '1953-10-22', 'Le Laos obtient sa pleine indépendance de la France.', NULL, 11),
('Proclamation de la République démocratique populaire lao', 'proclamation-republique-democratique-populaire-lao-LA', '1975-12-02', '1975-12-02', 'La monarchie est abolie et la République démocratique populaire lao est proclamée.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des cités phéniciennes', 'developpement-cites-pheniciennes-liban-LB', '0100-01-01', '0500-01-01', 'Les cités de la côte libanaise développent le commerce maritime et des réseaux d échanges en Méditerranée.', NULL, 25),
('Conquête perse de la Phénicie', 'conquete-perse-phenicie-liban-LB', '0539-01-01', '0539-01-01', 'La Phénicie passe sous la domination de l Empire achéménide après la conquête de la région par les Perses.', NULL, 12),
('Conquête d Alexandre le Grand', 'conquete-alexandre-grand-phenicie-liban-LB', '0332-01-01', '0332-01-01', 'Alexandre le Grand conquiert les cités phéniciennes de la région après le siège de Tyr.', NULL, 12),
('Développement hellénistique du Liban', 'developpement-hellenistique-liban-LB', '0064-01-01', '0330-01-01', 'La région connaît une forte influence culturelle grecque pendant la période hellénistique.', NULL, 24),
('Conquête romaine de la Phénicie', 'conquete-romaine-phenicie-liban-LB', '0064-01-01', '0064-01-01', 'La région est intégrée à l Empire romain et connaît un important développement urbain.', NULL, 12),
('Construction du temple de Bacchus à Baalbek', 'construction-temple-bacchus-baalbek-liban-LB', '0150-01-01', '0200-01-01', 'Le grand temple de Bacchus est construit à Baalbek pendant la période romaine.', NULL, 17),
('Développement de Baalbek romaine', 'developpement-baalbek-romaine-liban-LB', '0100-01-01', '0300-01-01', 'Baalbek devient un important centre religieux de la Syrie romaine.', NULL, 24),
('Diffusion du christianisme au Liban', 'diffusion-christianisme-liban-LB', '0300-01-01', '0600-01-01', 'Le christianisme se diffuse progressivement dans les villes et les montagnes du Liban.', NULL, 23),
('Conquête arabe du Liban', 'conquete-arabe-liban-LB', '0634-01-01', '0640-01-01', 'Les armées musulmanes conquièrent la région du Liban au cours de l expansion du califat.', NULL, 12),
('Développement de l émirat du Mont-Liban', 'developpement-emirat-mont-liban-LB', '0750-01-01', '1000-01-01', 'Les communautés montagnardes développent des structures politiques locales sous les différents pouvoirs régionaux.', NULL, 22),
('Conquête croisée de Beyrouth', 'conquete-croisee-beyrouth-liban-LB', '1110-01-01', '1110-01-01', 'Beyrouth est prise par les croisés et intégrée aux États latins d Orient.', NULL, 12),
('Reprise de Beyrouth par les Mamelouks', 'reprise-beyrouth-mamelouks-liban-LB', '1291-01-01', '1291-01-01', 'Les Mamelouks reprennent Beyrouth après la chute des principales positions franques du Levant.', NULL, 12),
('Conquête ottomane du Liban', 'conquete-ottomane-liban-LB', '1516-01-01', '1516-01-01', 'La région du Liban passe sous la domination de l Empire ottoman après la bataille de Marj Dabiq.', NULL, 12),
('Émirat de Fakhr ad-Din II', 'regne-fakhr-ad-din-ii-liban-LB', '1590-01-01', '1635-01-01', 'Fakhr ad-Din II renforce l autonomie politique du Mont-Liban et développe ses relations commerciales avec l Europe.', NULL, 5),
('Conflits du Mont-Liban de 1860', 'conflits-mont-liban-1860-LB', '1860-05-01', '1860-07-01', 'Des affrontements communautaires provoquent une grave crise politique et humanitaire au Mont-Liban.', NULL, 20),
('Création du Mutasarrifat du Mont-Liban', 'creation-mutasarrifat-mont-liban-LB', '1861-06-09', '1861-06-09', 'Un statut autonome est établi pour le Mont-Liban sous garantie des puissances européennes et de l Empire ottoman.', NULL, 22),
('Proclamation du Grand Liban', 'proclamation-grand-liban-LB', '1920-09-01', '1920-09-01', 'Le général Gouraud proclame l État du Grand Liban sous mandat français.', NULL, 22),
('Indépendance du Liban', 'independance-liban-LB', '1943-11-22', '1943-11-22', 'Le Liban obtient son indépendance et affirme la souveraineté de ses institutions nationales.', NULL, 11),
('Début de la guerre civile libanaise', 'guerre-civile-libanaise-LB', '1975-04-13', '1975-04-13', 'Des affrontements à Beyrouth marquent le début de la guerre civile libanaise.', NULL, 6),
('Accord de Taëf', 'accord-taef-liban-LB', '1989-10-22', '1989-10-22', 'L Accord de Taëf établit un cadre politique destiné à mettre fin à la guerre civile libanaise.', NULL, 14);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
